"""Read-only interpretation / audit of the bounded Entry experiment."""
import argparse,collections,csv,json,math,statistics
from pathlib import Path
from scripts import phase57_comprehensive_entry as m

def fmt(v):return '—' if v is None else f'{v:.4f}' if isinstance(v,float) else str(v)
def tab(head,rows):return '\n'.join(['| '+' | '.join(head)+' |','| '+' | '.join(['---']*len(head))+' |']+['| '+' | '.join(fmt(v) for v in row)+' |' for row in rows])
def run(source,out):
 source=Path(source);out=Path(out)
 if out.exists():raise FileExistsError(out)
 out.mkdir(parents=True);s=m.read(source/'summary.json');d=m.read(source/'train-diagnostics.json');p,ops,paths,selectors,legacy=m.sources();runtime=m.c.module('entry_report_fixed',m.c.RUNTIME)
 ledgers={k:m.read(source/f'validation-{k.lower()}.json.gz') for k in ('LINEAR','TREE')}
 for k,rs in ledgers.items():assert m.enc(m.panel(rs))==m.enc(s['validation'][k])
 # This supplement corrects interpretation of unequal denominators in the raw wait diagnostic.
 # It does not change labels, decisions, candidates, gates or any measured artifact.
 train=[x for x in ops if x['session'] in p['split']['TRAIN']];paired={};baseline=[]
 for x in train:
  b=m.eval_entry(x,paths[x['op']['anchorId']],0,runtime)
  if b and b['commonComplete']:baseline.append((x,b))
 for delay in (0,5,10,15,20,30):
  pairs=[]
  for x,b in baseline:
   e=m.eval_entry(x,paths[x['op']['anchorId']],delay,runtime);f=m.features(x,paths[x['op']['anchorId']],selectors[x['op']['anchorId']],legacy.get(x['op']['anchorId'],{}),m.c.minute(x['op']['opportunityTimestamp'])+delay)
   if e and e['commonComplete'] and f is not None:pairs.append((b,e))
  paired[str(delay)]={'baselineDenominator':len(baseline),'pairedN':len(pairs),'missing':len(baseline)-len(pairs),'priceImprovement':m.dist([100*(b['price']-e['price'])/b['price'] for b,e in pairs]),'baselineMAE':m.dist([b['common']['mae'] for b,e in pairs]),'delayedMAE':m.dist([e['common']['mae'] for b,e in pairs]),'baselineStrict30MAE':m.dist([b['strict30']['mae'] for b,e in pairs if b['strict30Complete'] and e['strict30Complete']]),'delayedStrict30MAE':m.dist([e['strict30']['mae'] for b,e in pairs if b['strict30Complete'] and e['strict30Complete']]),'preservation':{str(k):{'baselineWinners':sum(b['common']['mfe']>=k for _,b in baseline),'preserved':sum(b['common']['mfe']>=k and e['common']['mfe']>=k for b,e in pairs),'noEntryOrLost':sum(b['common']['mfe']>=k for _,b in baseline)-sum(b['common']['mfe']>=k and e['common']['mfe']>=k for b,e in pairs)} for k in (1,2,3,5)}}
 audits={};extra={}
 for kind,rs in ledgers.items():
  for r in rs:
   ts=r['timestamp'];last=ts
   for t in r['decision']['transitions']:
    assert t['timestamp']>=last;last=t['timestamp'];assert t['delay']<=30
   if r['entry']:
    a=r['entry']['candidateA'];b=r['entry']['fixed']
    if a and a['status']=='PROTECT_EXIT':assert a['exitBar']==a['signalBar']+1
    if a and a['status']=='FIXED12_FALLBACK':assert a['netPct']==b['netPct'] and a['exitBar']==b['exitBar']
  sessions={date:m.summary([r for r in rs if r['session']==date]) for date in sorted({r['session'] for r in rs})}
  baselineFull=[r['baseline'] for r in rs if r['baseline'] and r['baseline']['commonComplete']]
  grouped=collections.defaultdict(list)
  for r in rs:grouped[(r['session'],r['symbol'])].append(r)
  same=sum(sum(r['entry'] is not None for r in group)>1 for group in grouped.values())
  extra[kind]={'baselineComplete':{'n':len(baselineFull),'MAE':m.dist([b['common']['mae'] for b in baselineFull]),'MFE':m.dist([b['common']['mfe'] for b in baselineFull]),'strict30MAE':m.dist([b['strict30']['mae'] for b in baselineFull]),'fixed12':m.perf([b['fixed']['netPct'] for b in baselineFull if b['fixed']['status']=='EXIT_REFERENCE']),'candidateA':m.perf([b['candidateA']['netPct'] for b in baselineFull if b['candidateA']])},'sessions':sessions,'noReentryScope':'Within an independent opportunity episode only; source alternatives are not simultaneous funded trades.','symbolSessionWithTwoIndependentEntries':same,'unknownEconomicNeverZero':True}
  audits[kind]={'uniqueIdentities':len(rs)==len({r['id'] for r in rs}),'transitionChronology':True,'sameBarHighLowOrderingAssumed':False,'fixed12ExactFallback':True,'candidateANextOpenOrdering':True,'terminalStatesAccount':sum(collections.Counter(r['decision']['status'] for r in rs).values())==len(rs)}
 # Frozen model leaf audit: future best WAIT labels are an optimistic teacher, not an executable WAIT policy.
 tree=m.read(source/'model-tree.json')['tree'];leaves=[i for i,x in enumerate(tree['children_left']) if x==-1];leafvalues=[tree['value'][i] for i in leaves]
 supplement={'pairedTrainWaitStudy':paired,'validationAdditional':extra,'audit':audits,'treeLeaves':leafvalues,'verdictScope':'FAILED_PRECOMMITTED_TARGET_AND_TWO_MODEL_FAMILIES_NOT_PROOF_OF_PIT_INFORMATION_IMPOSSIBILITY','sharedTargetLimitation':'WAIT label uses future maximum utility among executable opens; optimistic oracle teacher can dominate BUY and promote systematic waiting/expiry. No test/data-dependent retune performed.','rawWaitStudyCaveat':'Raw per-offset denominators differ; use pairedTrainWaitStudy for preservation, not raw hits ratios.','pathClassCaveat':'CHOP is considered before IMMEDIATE inside the no-prior-negative-low branch; broad text precedence is ambiguous. Counts retained as descriptive only, never a training feature or gate.','intrabar':'High/low ordering within a bar is unknown. Time-to-high is hit-bar end upper bound, not exact touch time.','freshOOSOpened':False,'newDevelopmentTestOpened':False,'safety':p['safety']}
 m.write(out/'audit-appendix.json',supplement)
 lines=['# Comprehensive LONG Entry Intelligence — bounded Development result','', '**判定: COMPREHENSIVE_LONG_ENTRY_DEVELOPMENT_LIMIT_REACHED / 新EntryはFreezeしない。**','', 'この判定は、事前固定した2モデルと共有BUY/WAIT教師設計・利用可能な保存済みsubstrateに限定する。Entry研究全体やPIT情報全体の不可能性を証明していない。既存Frozen Opportunity Generatorを保持。Fresh/OOS、EXIT変更、Capitalへ進まずSTOP。','',f"Protocol commit: `{m.PROTOCOL_COMMIT}`。開始HEAD: `{p['sourceHead']}`。",'', '## Lineage / population','', '`FROZEN_LONG_SELECTOR_WITH_MIN_PRICE_75` → `phase57-new-long-entry-two-opportunity-v1` → 新しい独立counterfactual Entry episode。','', 'EXITは `NEW_LONG_EXIT_PROTECT_3_TO_1_FIXED12_V1` を無変更で呼び出す。BUY_NOWは研究上の価格参照でありbroker fillではない。INITIAL/DIPを別episodeで診断し、合計資本成績とはしない。','',tab(['Partition','sessions','Opportunities','date range'],[[k,len(v),s['population']['splitOpportunities'][k],v[0]+' … '+v[-1]] for k,v in p['split'].items()]),'', '全体3,508 = INITIAL 2,841 + DIP 667。TRAIN: 1,760件中633 complete episodes / 4,431 correlated state rows。1episode内のstate weight合計1。独立サンプルが4,431あるという主張はしない。VALIDATION: 863件中common60評価可能336。DEV TEST 885件は今回新たに評価していない。76 sessions自体は過去研究ですでにexposed。','', '## PIT inventory','',tab(['Status','Count'],list(s['inventory']['status'].items())), '', '合計66項目。承認43特徴 = Selector/time 10、price15 + path12、legacy context6。正確な名前・算式・coverageは feature-inventory.csv / train-diagnostics.json。旧anchorの一致は2,484/3,508 opportunities。旧featureはanchor時点のcontextであり、DIP/WAIT時点に更新された指標ではない。','', 'MISSINGは現在の全母集団にidentity整合で接続できる保存substrateがないことを意味し、Repoのどこにも存在しないという主張ではない。全銘柄のvolume/sector/market系列を新取得していない。欠測はTRAIN medianとmissing indicatorで表現。reference/missing prefixはfail-closed。','', '## TRAIN family diagnostics','',tab(['Family累積','features','BUY MAE','WAIT MAE','BUY RMSE','WAIT RMSE'],[[k,v['featureCount'],*v['MAE'],*v['RMSE']] for k,v in d['familyAblation'].items()]),'', '最初26 TRAIN sessions fit / 次12 TRAIN sessions診断。Validationを見たfeature選択なし。全43特徴を両候補へ事前指定通り投入。情報群追加の安定した増分価値は今回示せなかった。','', '## TRAIN paired wait diagnostic（採用候補ではない）','',tab(['Delay','paired n','価格改善mean','common-end MAE median','strict30 MAE median','+3 preserved/base','+5 preserved/base'],[[delay,v['pairedN'],v['priceImprovement']['mean'],v['delayedMAE']['median'],v['delayedStrict30MAE']['median'],str(v['preservation']['3']['preserved'])+'/'+str(v['preservation']['3']['baselineWinners']),str(v['preservation']['5']['preserved'])+'/'+str(v['preservation']['5']['baselineWinners'])] for delay,v in paired.items()]),'', 'common-endは待つほど保有可能時間が短くなる。MAE改善には時間短縮効果が含まれるのでstrict30も併記。元のtrain-location-study.jsonのoffset別nは異なるため、そのraw hit count比をpaired preservationとして使わない。Oracle最良OPENは改善余地の上限で、decisionには使わない。','', '## Candidate lineage / KEEP-KILL','',tab(['Candidate','architecture','Status','reason'],[['LINEAR','Ridge alpha10 / 2 utility outputs','KILL','Coverageと+3/+5 preservation壊滅'],['TREE','depth3 / min_leaf100 / seed57','KILL','Validation ENTER 0、winnerを全て捨てる']]),'', 'KEEP: 固定上流、PIT prefix projection、欠測明示、3状態ledger、paired preservationを必須にする評価。KILL: 今回の2モデル。係数・木・scalerを失敗再現用に保存し、active Entryへ昇格しない。','', '## Validation outcome','']
 lines += [tab(['Metric','LINEAR','TREE'],[[label,fn(s['validation']['LINEAR']['overall']),fn(s['validation']['TREE']['overall'])] for label,fn in [('all emitted',lambda z:z['opportunities']),('counterfactual ENTER all',lambda z:z['decisions'].get('COUNTERFACTUAL_ENTER',0)),('complete baseline',lambda z:z['commonComplete']),('complete entered',lambda z:z['enteredComplete']),('entry coverage',lambda z:z['entryRate']),('delay median min',lambda z:z['delay']['median']),('paired price improvement mean',lambda z:z['priceImprovement']['mean']),('paired price improvement median',lambda z:z['priceImprovement']['median']),('+3 remaining preservation',lambda z:z['preservation']['3']['rate']),('+5 remaining preservation',lambda z:z['preservation']['5']['rate'])]]),'']
 for kind,v in s['validation'].items():
  z=v['overall'];lines += [f'### {kind}','',tab(['source','complete n','ENTER complete','+3 preserved/base','+5 preserved/base'],[[k,w['commonComplete'],w['enteredComplete'],str(w['preservation']['3']['remainingWinners'])+'/'+str(w['preservation']['3']['baselineWinners']),str(w['preservation']['5']['remainingWinners'])+'/'+str(w['preservation']['5']['baselineWinners'])] for k,w in v['sources'].items()]),'',tab(['Economic arm','n','mean net %','median','PF','p05','Win fraction'],[[k,w['n'],w['mean'],w['median'],w['PF'],w['p05'],w['positiveRate']] for k,w in z['economic'].items() if k in ('baseline','candidateCashIncluded','executedOnlyBaseline','executedOnlyCandidate')]),'', 'Cash includedは見送りを0配分とした機会単位比較。未観測trade returnを0補完していない。各候補でeconomic evaluable denominatorは別（LINEAR 334 / TREE 336）。この差を隠して候補winnerを選ばない。全てKILL。','',tab(['Risk/Upside entered pair','baseline','candidate'],[[k,z[a][f],z[b][f]] for k,a,b,f in [('common MAE median','baselineMAEPaired','entryMAEPaired','median'),('common MAE p05','baselineMAEPaired','entryMAEPaired','p05'),('strict30 MAE median','strict30BaselinePaired','strict30EntryPaired','median'),('strict30 MAE p05','strict30BaselinePaired','strict30EntryPaired','p05'),('MFE median','baselineMFEPaired','entryMFEPaired','median')]]),'',tab(['tail','baseline all','baseline entered pair','candidate entered'],[[k,*w.values()] for k,w in z['tails'].items()]),'',tab(['Class','n','decision outcomes'],[[k,n,json.dumps(z['classDecisions'][k],ensure_ascii=False)] for k,n in z['pathClasses'].items()]),'',tab(['Gate','PASS'],list(v['gates'].items())),'',tab(['Chronological validation block','n','net delta'],[[k,w['commonComplete'],w['economic']['pairedDelta']['mean']] for k,w in v['blocks'].items()]),'',f"Top3 exclusion {v['top3']}: net delta {fmt(v['top3Excluded']['economic']['pairedDelta']['mean'])}pp。symbol HHI {fmt(v['concentration']['symbolHHI'])}。",'', 'session別はaudit-appendix、breadth/source/morning-afternoon別はsummaryに固定。これらを見た個別rule作成なし。','']
 lines += ['## Interpretation / important limits','', '- 少数の遅いEntryでは価格・MAE改善が見られるが、winnerを大量に失った。17件だけの良い数字をEntry完成と扱わない。', '- WAIT教師は将来のbest utilityという楽観的な上限。BUYと対等な実行可能継続価値ではなく、WAITを過大評価してexpiryへ偏らせ得る。これはshared objectiveの失敗でもあり、2モデルの失敗だけからPIT情報限界を一般化しない。', '- Opportunity分類のCHOP/IMMEDIATEの文章上の優先度には曖昧さがある。保存コードは「prior negative LOWがないbranch内でCHOP判定後にIMMEDIATE」。分類は説明用のみでmodel feature/gateには未使用。既存測定を書き換えて件数を整えない。', '- 同一5分barのHIGH/LOW順序は不明。adverseとfirst winnerが同一barのみならINCONCLUSIVE。到達時刻はhit bar終端の上限。', '- training coverage633/1760、validation336/863。session end・reference欠測・path欠測があるため、全3,508への有効性は認定できない。', '- 指定のvolatility別/missingness感度の十分な最終候補監査まで進めるsurvivorがない。固定subgroup集計は保存したが、Strong Candidate robustness PASSは主張しない。', '- 今回のbounded budgetは消化。次に検討するなら、WAITの実行可能continuation targetと完全なPIT snapshot coverageを別契約で設計する必要がある。今回それらを後付け変更してvalidationへ再適合しない。','', '## Audit / STOP','', 'SOURCE pinsとFrozen artifactsは不変。signalはcompleted prefixだけ、BUY referenceは次regular OPEN。Candidate Aはlater-bar signal→next OPEN、無signalはexact Fixed12。各Opportunityのdecisionは一度のみterminal。現物LONGのみ。Safety全9項目false。Fresh/OOS未開封。内部DEV TESTも新たなcandidate測定なし。','', 'tests / deterministic regeneration / GitHub CIの正確なHEADとrun identityは final-ci-receipt.json に記録。CI成功はperformance PASSではない。', '', '**DO_NOT_FREEZE。既存Opportunity Generatorをfallback保持し、この研究をSTOP。**','']
 (out/'REPORT.md').write_text('\n'.join(lines))
 m.write(out/'manifest.json',{'sourceManifest':m.sha(source/'manifest.json'),'code':m.sha(__file__),'outputPins':{f.name:m.sha(f) for f in sorted(out.iterdir())},'safety':p['safety']})
 print(json.dumps({'verdict':s['verdict'],'audit':audits,'pairedTrainN':{k:v['pairedN'] for k,v in paired.items()}}))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--source',required=True);p.add_argument('--out',required=True);a=p.parse_args();run(a.source,a.out)
